--#SET TERMINATOR @
BEGIN
   DECLARE CONTINUE HANDLER FOR SQLSTATE '42704' BEGIN END;
   EXECUTE IMMEDIATE 'DROP TABLE ERRORSCHEMA.ERRORTABLE';
END@

BEGIN 
   DECLARE v_errschema VARCHAR(20) DEFAULT 'ERRORSCHEMA';
   DECLARE v_errtab    VARCHAR(20) DEFAULT 'ERRORTABLE';
   CALL SYSPROC.ADMIN_DROP_SCHEMA('EZSCH', NULL, v_errschema, v_errtab);
END@
